+import { describe, expect, mock, test } from "bun:test";
+import * as products from "../src/products";
+import { getWishlist, removeFromWishlist, saveToWishlist } from "../src/wishlist";
+
+describe("wishlist", () => {
+  test("saves a catalogue product [wishlist/keep-a-wishlist#save-a-product]", () => {
+    const saved = saveToWishlist("c-save-a-product", "rain-jacket");
+    expect(saved.map((item) => item.productId)).toEqual(["rain-jacket"]);
+    expect(getWishlist("c-save-a-product").map((item) => item.productId)).toEqual(["rain-jacket"]);
+  });
+
+  test("refuses a product the catalogue does not hold [wishlist/keep-a-wishlist#catalogue-products-only]", () => {
+    expect(() => saveToWishlist("c-catalogue-products-only", "tent")).toThrow("Unknown product: tent");
+    expect(getWishlist("c-catalogue-products-only")).toEqual([]);
+  });
+
+  test("holds a product without a quantity [wishlist/keep-a-wishlist#no-quantity]", () => {
+    saveToWishlist("c-no-quantity", "wool-socks");
+    expect(getWishlist("c-no-quantity")).toEqual([
+      { productId: "wool-socks", name: "Wool socks", priceCents: 1200 },
+    ]);
+  });
+
+  test("keeps one entry where the first save put it [wishlist/keep-a-wishlist#saved-once]", () => {
+    saveToWishlist("c-saved-once", "wool-socks");
+    saveToWishlist("c-saved-once", "headlamp");
+    saveToWishlist("c-saved-once", "wool-socks");
+    expect(getWishlist("c-saved-once").map((item) => item.productId)).toEqual(["headlamp", "wool-socks"]);
+  });
+
+  test("removes a saved product [wishlist/keep-a-wishlist#remove-a-product]", () => {
+    saveToWishlist("c-remove-a-product", "rain-jacket");
+    saveToWishlist("c-remove-a-product", "wool-socks");
+    const left = removeFromWishlist("c-remove-a-product", "wool-socks");
+    expect(left.map((item) => item.productId)).toEqual(["rain-jacket"]);
+    expect(getWishlist("c-remove-a-product").map((item) => item.productId)).toEqual(["rain-jacket"]);
+  });
+
+  test("refuses to remove a product that is not saved [wishlist/keep-a-wishlist#remove-saved-only]", () => {
+    saveToWishlist("c-remove-saved-only", "rain-jacket");
+    expect(() => removeFromWishlist("c-remove-saved-only", "headlamp")).toThrow(
+      "Product headlamp is not on the wishlist",
+    );
+    expect(getWishlist("c-remove-saved-only").map((item) => item.productId)).toEqual(["rain-jacket"]);
+  });
+
+  test("shows one customer only their own saved items [wishlist/see-the-wishlist#one-list-per-customer]", () => {
+    saveToWishlist("c-one-list-per-customer-1", "headlamp");
+    expect(getWishlist("c-one-list-per-customer-1").map((item) => item.productId)).toEqual(["headlamp"]);
+    expect(getWishlist("c-one-list-per-customer-2")).toEqual([]);
+  });
+
+  test("reads an empty wishlist for a customer who has saved nothing [wishlist/see-the-wishlist#empty-wishlist]", () => {
+    expect(getWishlist("c-empty-wishlist")).toEqual([]);
+  });
+
+  test("shows the price the catalogue holds now [wishlist/see-the-wishlist#price-now]", () => {
+    saveToWishlist("c-price-now", "rain-jacket");
+    expect(getWishlist("c-price-now")).toEqual([
+      { productId: "rain-jacket", name: "Rain jacket", priceCents: 1990 },
+    ]);
+
+    const catalogueGetProduct = products.getProduct;
+    mock.module("../src/products", () => ({
+      ...products,
+      getProduct: (id: string) => ({ ...catalogueGetProduct(id), priceCents: 2490 }),
+    }));
+    try {
+      expect(getWishlist("c-price-now")).toEqual([
+        { productId: "rain-jacket", name: "Rain jacket", priceCents: 2490 },
+      ]);
+    } finally {
+      mock.module("../src/products", () => ({ ...products, getProduct: catalogueGetProduct }));
+    }
+    expect(getWishlist("c-price-now")).toEqual([
+      { productId: "rain-jacket", name: "Rain jacket", priceCents: 1990 },
+    ]);
+  });
+
+  test("shows the most recently saved item first [wishlist/see-the-wishlist#newest-first]", () => {
+    saveToWishlist("c-newest-first", "wool-socks");
+    saveToWishlist("c-newest-first", "headlamp");
+    expect(getWishlist("c-newest-first").map((item) => item.name)).toEqual(["Headlamp", "Wool socks"]);
+  });
+});
